css:
.loader {
  position: relative;
  width: 52px;
  height: 52px;
}
.loader i {
  position: absolute;
  top: 6px;
  left: 6px;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 4px solid #6366f1;
  box-sizing: border-box;
  animation: scan 2s ease-in-out infinite;
}
.loader i::after {
  content: "";
  position: absolute;
  bottom: -9px;
  right: -3px;
  width: 4px;
  height: 12px;
  border-radius: 2px;
  background: #6366f1;
  transform: rotate(-45deg);
}
@keyframes scan {
  0%, 100% { transform: translate(0, 0); }
  25% { transform: translate(20px, 2px); }
  50% { transform: translate(18px, 20px); }
  75% { transform: translate(2px, 18px); }
}
